package com.imageproc.pipeline

import java.sql.Connection
import java.sql.DriverManager
import java.util.concurrent.ConcurrentLinkedQueue
import java.util.concurrent.atomic.AtomicInteger
import java.security.MessageDigest
import java.io.File
import java.nio.file.Paths
import java.nio.file.Files

class ConnectionPool(private val maxSize: Int = 10) {
    private val pool = ConcurrentLinkedQueue<Connection>()
    private val activeCount = AtomicInteger(0)
    private val dbUrl = System.getenv("DB_URL") ?: "jdbc:h2:mem:imagedb"

    fun acquire(): Connection {
        pool.poll()?.let { if (!it.isClosed) return it else activeCount.decrementAndGet() }
        if (activeCount.get() < maxSize) {
            activeCount.incrementAndGet()
            return DriverManager.getConnection(dbUrl)
        }
        throw IllegalStateException("Pool exhausted")
    }

    fun release(conn: Connection) {
        if (!conn.isClosed) pool.offer(conn) else activeCount.decrementAndGet()
    }
}

data class ImageTask(
    val taskId: String,
    val sourceUrl: String,
    val outputFormat: String,
    val quality: Int,
    val metadata: Map<String, String>
)

class ImageFormatValidator {
    private val allowedFormats = setOf("png", "jpg", "jpeg", "webp", "gif", "tiff")
    private val formatAliases = mapOf(
        "jpeg" to "jpg",
        "tiff" to "tif"
    )

    fun normalize(format: String): String {
        val lower = format.lowercase().trim()
        return formatAliases.getOrDefault(lower, lower)
    }

    fun isValid(format: String): Boolean {
        return normalize(format) in allowedFormats || format.lowercase() in allowedFormats
    }
}

class ImageMetadataEncoder {
    fun encodeForExiftool(metadata: Map<String, String>): List<String> {
        return metadata.map { (key, value) ->
            val sanitizedKey = key.replace(Regex("[^a-zA-Z0-9_]"), "")
            val sanitizedValue = sanitizeMetadataValue(value)
            "-${sanitizedKey}=${sanitizedValue}"
        }
    }

    private fun sanitizeMetadataValue(value: String): String {
        // Remove shell metacharacters from the value
        return value.replace(Regex("[;&|`\$(){}\[\]<>!#~]"), "")
    }
}

class ConversionCommandBuilder(
    private val validator: ImageFormatValidator,
    private val metadataEncoder: ImageMetadataEncoder
) {
    private val basePath = "/usr/local/bin"
    private val workDir = "/tmp/imageproc"

    fun buildConversionCommand(task: ImageTask, inputPath: String): List<String> {
        val format = validator.normalize(task.outputFormat)
        if (!validator.isValid(format)) {
            throw IllegalArgumentException("Invalid format: ${task.outputFormat}")
        }

        val outputFile = computeOutputPath(task.taskId, format)
        val qualityArgs = buildQualityArgs(task.quality, format)

        return listOf(
            "$basePath/convert",
            inputPath,
            *qualityArgs.toTypedArray(),
            outputFile
        )
    }

    fun buildMetadataCommand(task: ImageTask, filePath: String): List<String> {
        val metadataArgs = metadataEncoder.encodeForExiftool(task.metadata)
        // Build command as argument list - no shell interpretation
        return listOf("$basePath/exiftool") + metadataArgs + listOf(filePath)
    }

    private fun buildQualityArgs(quality: Int, format: String): List<String> {
        val clampedQuality = quality.coerceIn(1, 100)
        return when (format) {
            "jpg" -> listOf("-quality", "$clampedQuality")
            "webp" -> listOf("-quality", "$clampedQuality")
            "png" -> listOf("-define", "png:compression-level=${9 - (clampedQuality / 12)}")
            else -> emptyList()
        }
    }

    private fun computeOutputPath(taskId: String, format: String): String {
        val hash = MessageDigest.getInstance("SHA-256")
            .digest(taskId.toByteArray())
            .joinToString("") { "%02x".format(it) }
            .take(16)
        return "$workDir/output_${hash}.$format"
    }
}

class ImageProcessingPipeline(
    private val pool: ConnectionPool,
    private val commandBuilder: ConversionCommandBuilder
) {
    fun processTask(task: ImageTask): Result<String> {
        return runCatching {
            val conn = pool.acquire()
            try {
                logTaskStart(conn, task)
                val inputPath = downloadSource(task.sourceUrl, task.taskId)

                // Step 1: Convert image format
                val conversionCmd = commandBuilder.buildConversionCommand(task, inputPath)
                executeCommand(conversionCmd)

                // Step 2: Write metadata using exiftool
                val outputPath = conversionCmd.last()
                if (task.metadata.isNotEmpty()) {
                    val metadataCmd = commandBuilder.buildMetadataCommand(task, outputPath)
                    executeCommand(metadataCmd)
                }

                logTaskComplete(conn, task)
                outputPath
            } finally {
                pool.release(conn)
            }
        }
    }

    private fun downloadSource(url: String, taskId: String): String {
        val hash = MessageDigest.getInstance("SHA-256")
            .digest(taskId.toByteArray())
            .joinToString("") { "%02x".format(it) }
            .take(16)
        val path = "/tmp/imageproc/input_$hash"
        // Simulated download - in production would use HTTP client
        if (!File(path).exists()) {
            Files.createDirectories(Paths.get("/tmp/imageproc"))
            File(path).createNewFile()
        }
        return path
    }

    private fun executeCommand(cmd: List<String>) {
        val process = ProcessBuilder(cmd)
            .directory(File("/tmp/imageproc"))
            .redirectErrorStream(true)
            .start()
        val exitCode = process.waitFor()
        if (exitCode != 0) {
            val error = process.inputStream.bufferedReader().readText()
            throw RuntimeException("Command failed ($exitCode): $error")
        }
    }

    private fun logTaskStart(conn: Connection, task: ImageTask) {
        val stmt = conn.prepareStatement(
            "INSERT INTO task_log (task_id, status, started_at) VALUES (?, 'STARTED', NOW())"
        )
        stmt.setString(1, task.taskId)
        stmt.executeUpdate()
    }

    private fun logTaskComplete(conn: Connection, task: ImageTask) {
        val stmt = conn.prepareStatement(
            "UPDATE task_log SET status = 'COMPLETE', finished_at = NOW() WHERE task_id = ?"
        )
        stmt.setString(1, task.taskId)
        stmt.executeUpdate()
    }
}

fun main() {
    val pool = ConnectionPool()
    val validator = ImageFormatValidator()
    val metadataEncoder = ImageMetadataEncoder()
    val commandBuilder = ConversionCommandBuilder(validator, metadataEncoder)
    val pipeline = ImageProcessingPipeline(pool, commandBuilder)

    val task = ImageTask(
        taskId = "task-001",
        sourceUrl = "https://cdn.example.com/photo.jpg",
        outputFormat = "webp",
        quality = 85,
        metadata = mapOf("Author" to "John Doe", "Copyright" to "2024")
    )

    val result = pipeline.processTask(task)
    result.onSuccess { println("Output: $it") }
    result.onFailure { println("Error: ${it.message}") }
}
